15.2 Generators com yield
Uma função generator produz valores sob demanda, mantendo o estado entre chamadas, sem construir a coleção inteira na memória:
def contar_ate(n):
    i = 1
    while i &lt;= n:
        yield i          # devolve um valor e "pausa" aqui
        i += 1

for numero in contar_ate(5):
    print(numero)        # 1, 2, 3, 4, 5
Generators podem ser infinitos — quem consome decide quando parar:
def naturais():
    n = 0
    while True:
        yield n
        n += 1

import time

def cronometrar(func):
    def wrapper(*args, **kwargs):
        inicio = time.perf_counter()
        resultado = func(*args, **kwargs)
        print(f"{func.__name__} levou {time.perf_counter() - inicio:.4f}s")
        return resultado
    return wrapper


@cronometrar                       # equivale a: processar = cronometrar(processar)
def processar(n):
    return sum(range(n))

processar(1_000_000)

16.2 Decorators com parâmetros
def repetir(n):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(n):
                resultado = func(*args, **kwargs)
            return resultado
        return wrapper
    return decorator

@repetir(3)
def cumprimentar():
    print("Olá!")

