28.4 Exemplo aplicado: parênteses balanceados
def balanceada(expressao: str) -&gt; bool:
    pares = {")": "(", "]": "[", "}": "{"}
    pilha = Pilha()
    for caractere in expressao:
        if caractere in "([{":
            pilha.push(caractere)
        elif caractere in ")]}":
            if pilha.is_empty() or pilha.pop() != pares[caractere]:
                return False
    return pilha.is_empty()

print(balanceada("(a + b) * [c - d]"))   # True
print(balanceada("(a + b]"))             # False
print(balanceada("((a + b)"))            # False

29.3 Implementação com collections.deque
from collections import deque

class Fila:
    def __init__(self):
        self._itens: deque = deque()

    def enqueue(self, item) -&gt; None:
        self._itens.append(item)        # entra no final

    def dequeue(self):
        if self.is_empty():
            raise IndexError("dequeue em fila vazia")
        return self._itens.popleft()    # sai pela frente — O(1)

    def front(self):
        if self.is_empty():
            raise IndexError("front em fila vazia")
        return self._itens[0]

    def is_empty(self) -&gt; bool:
        return not self._itens

    def __len__(self) -&gt; int:
        return len(self._itens)

    def __repr__(self) -&gt; str:
        return f"Fila(frente → trás: {list(self._itens)})"


f = Fila()
f.enqueue("Ana")
f.enqueue("Bruno")
f.enqueue("Carla")
print(f)              # Fila(frente → trás: ['Ana', 'Bruno', 'Carla'])
print(f.dequeue())    # Ana  (primeira a entrar, primeira a sair)
print(f.front())      # Bruno

