30.2 A lista ligada
class ListaLigada:
    def __init__(self):
        self.cabeca: Optional[No] = None

    def inserir_inicio(self, valor) -&gt; None:     # O(1)
        novo = No(valor)
        novo.proximo = self.cabeca
        self.cabeca = novo

    def inserir_fim(self, valor) -&gt; None:        # O(n)
        novo = No(valor)
        if not self.cabeca:
            self.cabeca = novo
            return
        atual = self.cabeca
        while atual.proximo:
            atual = atual.proximo
        atual.proximo = novo

    def buscar(self, valor) -&gt; bool:             # O(n)
        atual = self.cabeca
        while atual:
            if atual.valor == valor:
                return True
            atual = atual.proximo
        return False

    def percorrer(self) -&gt; None:
        atual = self.cabeca
        while atual:
            print(atual.valor, end=" -&gt; ")
            atual = atual.proximo
        print("None")


lista = ListaLigada()
lista.inserir_inicio(3)
lista.inserir_inicio(2)
lista.inserir_fim(4)
lista.percorrer()        # 2 -&gt; 3 -&gt; 4 -&gt; None

from dataclasses import dataclass
from typing import Optional

@dataclass
class NoArvore:
    valor: int
    esquerda: Optional["NoArvore"] = None
    direita: Optional["NoArvore"] = None


class ArvoreBusca:
    def __init__(self):
        self.raiz: Optional[NoArvore] = None

    def inserir(self, valor: int) -&gt; None:
        self.raiz = self._inserir(self.raiz, valor)

    def _inserir(self, no, valor):
        if no is None:                          # caso base da recursão
            return NoArvore(valor)
        if valor &lt; no.valor:
            no.esquerda = self._inserir(no.esquerda, valor)
        else:
            no.direita = self._inserir(no.direita, valor)
        return no

    def buscar(self, valor: int) -&gt; bool:       # O(log n) se balanceada
        no = self.raiz
        while no:
            if valor == no.valor:
                return True
            no = no.esquerda if valor &lt; no.valor else no.direita
        return False

    def em_ordem(self, no, resultado=None) -&gt; list:
        if resultado is None:
            resultado = []
        if no:
            self.em_ordem(no.esquerda, resultado)   # recursão (Capítulo 26)!
            resultado.append(no.valor)
            self.em_ordem(no.direita, resultado)
        return resultado


arv = ArvoreBusca()
for v in [5, 3, 8, 1, 4, 7]:
    arv.inserir(v)
print(arv.em_ordem(arv.raiz))    # [1, 3, 4, 5, 7, 8] — sai ordenado!
print(arv.buscar(4))             # True

31.2 Percursos

Em ordem (esquerda, raiz, direita): produz os valores ordenados numa BST;
Pré-ordem (raiz, esquerda, direita): útil para copiar/serializar a árvore;
Pós-ordem (esquerda, direita, raiz): útil para liberar/avaliar de baixo para cima.

A recursão é a ferramenta natural: a definição “visite a subárvore esquerda, o nó, a subárvore direita” é o código.

from collections import defaultdict, deque

class Grafo:
    def __init__(self):
        self.adjacencia: defaultdict = defaultdict(list)

    def adicionar_aresta(self, u, v) -&gt; None:
        self.adjacencia[u].append(v)
        self.adjacencia[v].append(u)     # não-direcionado; remova p/ direcionado

    def bfs(self, inicio) -&gt; list:
        """Busca em largura — usa FILA (Capítulo 29)."""
        visitados = {inicio}
        fila = deque([inicio])
        ordem = []
        while fila:
            no = fila.popleft()
            ordem.append(no)
            for vizinho in self.adjacencia[no]:
                if vizinho not in visitados:
                    visitados.add(vizinho)
                    fila.append(vizinho)
        return ordem

    def dfs(self, inicio, visitados=None) -&gt; list:
        """Busca em profundidade — usa PILHA via recursão (Capítulos 26 e 28)."""
        if visitados is None:
            visitados = set()
        visitados.add(inicio)
        ordem = [inicio]
        for vizinho in self.adjacencia[inicio]:
            if vizinho not in visitados:
                ordem += self.dfs(vizinho, visitados)
        return ordem


g = Grafo()
for u, v in [("A", "B"), ("A", "C"), ("B", "D"), ("C", "D")]:
    g.adicionar_aresta(u, v)

print(g.bfs("A"))    # ['A', 'B', 'C', 'D'] — expande por camadas
print(g.dfs("A"))    # ['A', 'B', 'D', 'C'] — vai fundo antes de voltar

